"""Server-owned repository for credential records stored in Vault."""

from __future__ import annotations

import json
from typing import NamedTuple

from loguru import logger

from authsome.auth.models.connection import (
    ConnectionRecord,
    ProviderClientRecord,
    ProviderMetadataRecord,
    ProviderStateRecord,
)
from authsome.vault import Vault


class StoreKeyParts(NamedTuple):
    """Parsed components of a credential store key."""

    vault: str | None = None
    identity: str | None = None
    provider: str | None = None
    record_type: str | None = None
    connection: str | None = None


def build_store_key(
    *,
    vault: str | None = None,
    identity: str | None = None,
    provider: str | None = None,
    record_type: str | None = None,
    connection: str | None = None,
) -> str:
    """Build a namespaced key for server-owned credential storage."""
    if record_type == "definition" and provider:
        return f"provider:{provider}:definition"
    if record_type == "server" and provider:
        return f"server:provider:{provider}:client"

    if vault and provider:
        if record_type == "metadata":
            return f"vault:{vault}:{provider}:metadata"
        if record_type == "state":
            return f"vault:{vault}:{provider}:state"
        if record_type == "connection" and connection:
            return f"vault:{vault}:{provider}:connection:{connection}"
        if record_type == "client":
            return f"vault:{vault}:{provider}:client"

    if identity and provider:
        if record_type == "metadata":
            return f"identity:{identity}:{provider}:metadata"
        if record_type == "state":
            return f"identity:{identity}:{provider}:state"
        if record_type == "connection" and connection:
            return f"identity:{identity}:{provider}:connection:{connection}"
        if record_type == "client":
            return f"identity:{identity}:{provider}:client"

    raise ValueError(
        f"Cannot build store key with vault={vault}, identity={identity}, provider={provider}, "
        f"record_type={record_type}, connection={connection}"
    )


def parse_store_key(key: str) -> StoreKeyParts:
    """Parse a credential store key into its components."""
    if key.startswith("provider:") and key.endswith(":definition"):
        provider = key[len("provider:") : -len(":definition")]
        return StoreKeyParts(provider=provider, record_type="definition")

    if key.startswith("server:provider:") and key.endswith(":client"):
        provider = key[len("server:provider:") : -len(":client")]
        return StoreKeyParts(provider=provider, record_type="server")

    if key.startswith("vault:"):
        parts = key.split(":", 2)
        if len(parts) < 3:
            return StoreKeyParts()
        vault = parts[1]
        remainder = parts[2]

        if remainder.endswith(":metadata"):
            return StoreKeyParts(vault=vault, provider=remainder[:-9], record_type="metadata")
        if remainder.endswith(":state"):
            return StoreKeyParts(vault=vault, provider=remainder[:-6], record_type="state")
        if remainder.endswith(":client"):
            return StoreKeyParts(vault=vault, provider=remainder[:-7], record_type="client")

        if ":connection:" in remainder:
            provider, _, connection = remainder.partition(":connection:")
            return StoreKeyParts(
                vault=vault,
                provider=provider,
                record_type="connection",
                connection=connection,
            )

    if key.startswith("identity:"):
        parts = key.split(":", 2)
        if len(parts) < 3:
            return StoreKeyParts()
        identity = parts[1]
        remainder = parts[2]

        if remainder.endswith(":metadata"):
            return StoreKeyParts(identity=identity, provider=remainder[:-9], record_type="metadata")
        if remainder.endswith(":state"):
            return StoreKeyParts(identity=identity, provider=remainder[:-6], record_type="state")
        if remainder.endswith(":client"):
            return StoreKeyParts(identity=identity, provider=remainder[:-7], record_type="client")

        if ":connection:" in remainder:
            provider, _, connection = remainder.partition(":connection:")
            return StoreKeyParts(
                identity=identity,
                provider=provider,
                record_type="connection",
                connection=connection,
            )

    return StoreKeyParts()


class CredentialRepository:
    """Persist Authsome credential records in vault-backed namespaces."""

    def __init__(
        self,
        vault: Vault,
        *,
        identity: str | None,
        principal_id: str | None,
        vault_id: str,
    ) -> None:
        self._vault = vault
        self._identity = identity
        self._principal_id = principal_id
        self._vault_id = vault_id

    @property
    def vault(self) -> Vault:
        return self._vault

    @property
    def vault_id(self) -> str:
        return self._vault_id

    @property
    def collection(self) -> str:
        return f"vault:{self._vault_id}"

    @property
    def server_collection(self) -> str:
        return "server"

    async def list_connection_keys(self) -> list[str]:
        prefix = f"vault:{self._vault_id}:"
        keys = await self._vault.list(prefix, collection=self.collection)
        return [key for key in keys if parse_store_key(key).record_type == "connection"]

    async def get_connection(self, provider: str, connection: str) -> ConnectionRecord | None:
        key = build_store_key(
            vault=self._vault_id,
            provider=provider,
            record_type="connection",
            connection=connection,
        )
        raw = await self._vault.get(key, collection=self.collection)
        if raw is None:
            return None
        return self.load_connection_record(raw, key)

    async def save_connection(self, record: ConnectionRecord) -> None:
        record.identity = self._identity
        record.principal_id = self._principal_id
        record.vault_id = self._vault_id
        key = build_store_key(
            vault=self._vault_id,
            provider=record.provider,
            record_type="connection",
            connection=record.connection_name,
        )
        await self._vault.put(key, record.model_dump_json(), collection=self.collection)

    async def delete_connection(self, provider: str, connection: str) -> None:
        key = build_store_key(
            vault=self._vault_id,
            provider=provider,
            record_type="connection",
            connection=connection,
        )
        await self._vault.delete(key, collection=self.collection)

    async def get_provider_metadata(self, provider: str) -> ProviderMetadataRecord | None:
        key = build_store_key(vault=self._vault_id, provider=provider, record_type="metadata")
        raw = await self._vault.get(key, collection=self.collection)
        return ProviderMetadataRecord.model_validate_json(raw) if raw else None

    async def save_provider_metadata(self, record: ProviderMetadataRecord) -> None:
        record.identity = self._identity
        record.principal_id = self._principal_id
        record.vault_id = self._vault_id
        key = build_store_key(vault=self._vault_id, provider=record.provider, record_type="metadata")
        await self._vault.put(key, record.model_dump_json(), collection=self.collection)

    async def delete_provider_metadata(self, provider: str) -> None:
        key = build_store_key(vault=self._vault_id, provider=provider, record_type="metadata")
        await self._vault.delete(key, collection=self.collection)

    async def get_provider_state(self, provider: str) -> ProviderStateRecord | None:
        key = build_store_key(vault=self._vault_id, provider=provider, record_type="state")
        raw = await self._vault.get(key, collection=self.collection)
        return ProviderStateRecord.model_validate_json(raw) if raw else None

    async def save_provider_state(self, record: ProviderStateRecord) -> None:
        record.identity = self._identity
        record.principal_id = self._principal_id
        record.vault_id = self._vault_id
        key = build_store_key(vault=self._vault_id, provider=record.provider, record_type="state")
        await self._vault.put(key, record.model_dump_json(), collection=self.collection)

    async def get_provider_client(self, provider: str) -> ProviderClientRecord | None:
        key = build_store_key(provider=provider, record_type="server")
        raw = await self._vault.get(key, collection=self.server_collection)
        return ProviderClientRecord.model_validate_json(raw) if raw else None

    async def save_provider_client(self, record: ProviderClientRecord) -> None:
        key = build_store_key(provider=record.provider, record_type="server")
        await self._vault.put(key, record.model_dump_json(), collection=self.server_collection)

    async def delete_provider_client(self, provider: str) -> None:
        key = build_store_key(provider=provider, record_type="server")
        await self._vault.delete(key, collection=self.server_collection)

    @staticmethod
    def load_connection_record(raw: str, key: str) -> ConnectionRecord | None:
        try:
            data = json.loads(raw)
        except json.JSONDecodeError:
            logger.warning("Corrupt record at key {}", key)
            return None
        if data.get("schema_version", 1) < 2:
            return None
        return ConnectionRecord.model_validate(data)

"""Server-owned secret resolution for root key material."""

from __future__ import annotations

import base64
import os
import secrets
from dataclasses import dataclass
from pathlib import Path

from loguru import logger

from authsome.paths import get_server_home

_KEY_SIZE = 32
_KEYRING_SERVICE = "authsome"

MASTER_KEY_ENV = "AUTHSOME_MASTER_KEY"
MASTER_KEY_FILE_ENV = "AUTHSOME_MASTER_KEY_FILE"
UI_SESSION_KEY_ENV = "AUTHSOME_UI_SESSION_KEY"
UI_SESSION_KEY_FILE_ENV = "AUTHSOME_UI_SESSION_KEY_FILE"


@dataclass(frozen=True)
class ServerSecretSpec:
    """Configuration for resolving one server-owned secret."""

    env_var: str
    file_env_var: str
    default_filename: str
    keyring_username: str
    description: str


MASTER_SECRET = ServerSecretSpec(
    env_var=MASTER_KEY_ENV,
    file_env_var=MASTER_KEY_FILE_ENV,
    default_filename="master.key",
    keyring_username="master_key",
    description="master secret",
)

UI_SESSION_SECRET = ServerSecretSpec(
    env_var=UI_SESSION_KEY_ENV,
    file_env_var=UI_SESSION_KEY_FILE_ENV,
    default_filename="ui_session_secret.key",
    keyring_username="ui_session_key",
    description="UI session signing secret",
)


class ServerSecretResolver:
    """Resolve server-owned secrets from env, file, keyring, or generated fallback."""

    def __init__(self, spec: ServerSecretSpec, home: Path | None = None) -> None:
        self._spec = spec
        self._server_home = get_server_home(home)
        self._default_key_file = self._server_home / spec.default_filename

    def resolve(self) -> str:
        value = os.environ.get(self._spec.env_var)
        if value and value.strip():
            return value.strip()

        key_file = self._key_file_path()
        if key_file.exists():
            content = key_file.read_text(encoding="utf-8").strip()
            if content:
                return content

        keyring_value = self._read_keyring()
        if keyring_value:
            return keyring_value

        generated = base64.b64encode(secrets.token_bytes(_KEY_SIZE)).decode("ascii")
        if self._write_keyring(generated):
            logger.info("Generated and stored new {} in OS keyring", self._spec.description)
        else:
            self._write_file(self._default_key_file, generated)
            logger.info("Generated new {} at {}", self._spec.description, self._default_key_file)
        return generated

    def _key_file_path(self) -> Path:
        custom = os.environ.get(self._spec.file_env_var)
        return Path(custom) if custom else self._default_key_file

    def _read_keyring(self) -> str | None:
        try:
            import keyring

            return keyring.get_password(_KEYRING_SERVICE, self._spec.keyring_username)
        except Exception:
            return None

    def _write_keyring(self, value: str) -> bool:
        try:
            import keyring

            keyring.set_password(_KEYRING_SERVICE, self._spec.keyring_username, value)
            return True
        except Exception:
            return False

    def _write_file(self, path: Path, value: str) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(value, encoding="utf-8")
        try:
            os.chmod(path, 0o600)
        except OSError:
            pass


def load_master_secret(home: Path | None = None) -> str:
    """Load or create the server-owned vault master secret."""
    return ServerSecretResolver(MASTER_SECRET, home).resolve()


def load_ui_session_signing_secret(home: Path | None = None) -> str:
    """Load or create the server-owned UI session signing secret."""
    return ServerSecretResolver(UI_SESSION_SECRET, home).resolve()

"""Auth session routes and browser input pages."""

from __future__ import annotations

from datetime import timedelta
from typing import Any

from fastapi import APIRouter, BackgroundTasks, Depends, HTTPException, Request
from fastapi.responses import HTMLResponse, RedirectResponse, Response

from authsome.auth.input_provider import InputField
from authsome.auth.models.enums import AuthType, FlowType
from authsome.auth.sessions import AuthSession, AuthSessionStatus, AuthSessionStore
from authsome.server.analytics import capture_event
from authsome.server.credential_service import AuthService
from authsome.server.routes._deps import (
    get_auth_sessions,
    get_protected_auth_service,
    get_server_base_url,
    require_auth_service,
    resolve_ui_request_identity,
)
from authsome.server.schemas import (
    AuthSessionResponse,
    BrowserAction,
    NoneAction,
    OpenUrlAction,
    ResumeAuthSessionRequest,
    StartAuthSessionRequest,
)
from authsome.server.urls import build_auth_input_url, build_callback_url, build_device_url
from authsome.server.web_pages import pages
from authsome.utils import utc_now

router = APIRouter(prefix="/auth", tags=["auth"])


def _ui_session_required(session: AuthSession) -> bool:
    return bool(session.payload.get("ui_session_required"))


async def _ensure_browser_session_identity(request: Request, session: AuthSession) -> bool:
    if not _ui_session_required(session):
        return True
    await resolve_ui_request_identity(request)
    return getattr(request.state, "ui_principal_id", None) == session.principal_id


async def _load_session_or_404(sessions: AuthSessionStore, session_id: str) -> AuthSession:
    """Return an auth session or raise the route-level not-found response."""
    try:
        return await sessions.get(session_id)
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="Authentication session not found") from exc


def _event_actor(session: AuthSession) -> str:
    return session.identity or session.principal_id or "account-ui"


@router.post("/sessions", response_model=AuthSessionResponse)
async def start_session(
    body: StartAuthSessionRequest,
    background_tasks: BackgroundTasks,
    auth: AuthService = Depends(get_protected_auth_service),
    sessions: AuthSessionStore = Depends(get_auth_sessions),
    server_base_url: str = Depends(get_server_base_url),
) -> AuthSessionResponse:
    definition = await auth.get_provider(body.provider)
    flow = FlowType(body.flow) if body.flow else definition.flow
    session = await sessions.create(
        provider=body.provider,
        identity=auth.identity,
        principal_id=auth.principal_id,
        connection_name=body.connection,
        flow_type=flow.value,
    )
    session.payload["force"] = body.force
    session.payload["callback_url_override"] = build_callback_url(server_base_url)
    if body.scopes is not None:
        session.payload["requested_scopes"] = body.scopes
    if body.base_url is not None:
        session.payload["base_url"] = body.base_url

    if not body.force:
        try:
            existing = await auth.get_connection(body.provider, body.connection)
            if auth._connection_is_valid(existing) and auth._requested_context_matches(
                existing,
                scopes=body.scopes,
                base_url=body.base_url,
            ):
                session.state = AuthSessionStatus.COMPLETED
                session.status_message = "Already connected"
                await sessions.save(session)
                return _session_response(session, server_base_url)
        except Exception:
            pass

    fields = await auth.get_required_inputs(session, scopes=body.scopes, base_url=body.base_url)
    if fields:
        session.state = AuthSessionStatus.WAITING_FOR_USER
        session.payload["input_fields"] = [_field_to_payload(field) for field in fields]
        await sessions.save(session)
        return _session_response(session, server_base_url)

    await auth.begin_login_flow(
        session=session,
        scopes=body.scopes,
        force=body.force,
        base_url=body.base_url,
    )
    if FlowType(session.flow_type) == FlowType.DEVICE_CODE:
        _update_device_code_expiry(sessions, session)
        background_tasks.add_task(auth.background_resume, session)
    await sessions.index_oauth_state(session)
    capture_event(
        _event_actor(session),
        "auth session started",
        {
            "provider": session.provider,
            "flow_type": session.flow_type,
            "principal_id": session.principal_id,
        },
    )
    return _session_response(session, server_base_url)


@router.get("/sessions/{session_id}", response_model=AuthSessionResponse)
async def get_session(
    session_id: str,
    auth: AuthService = Depends(get_protected_auth_service),
    sessions: AuthSessionStore = Depends(get_auth_sessions),
    server_base_url: str = Depends(get_server_base_url),
) -> AuthSessionResponse:
    session = await _load_session_or_404(sessions, session_id)
    if session.identity != auth.identity:
        raise HTTPException(status_code=404, detail="Authentication session not found")
    return _session_response(session, server_base_url)


@router.post("/sessions/{session_id}/resume", response_model=AuthSessionResponse)
async def resume_session(
    session_id: str,
    body: ResumeAuthSessionRequest,
    auth: AuthService = Depends(get_protected_auth_service),
    sessions: AuthSessionStore = Depends(get_auth_sessions),
    server_base_url: str = Depends(get_server_base_url),
) -> AuthSessionResponse:
    session = await _load_session_or_404(sessions, session_id)
    if session.identity != auth.identity:
        raise HTTPException(status_code=404, detail="Authentication session not found")
    try:
        record = await auth.resume_login_flow(session, body.data)
        if record is None:
            session.state = AuthSessionStatus.WAITING_FOR_USER
        else:
            session.state = AuthSessionStatus.COMPLETED
            session.status_message = "Login successful"
            capture_event(
                _event_actor(session),
                "auth session completed",
                {
                    "provider": session.provider,
                    "flow_type": session.flow_type,
                    "principal_id": session.principal_id,
                },
            )
        await sessions.save(session)
    except Exception as exc:
        session.state = AuthSessionStatus.FAILED
        session.error_message = str(exc)
        await sessions.save(session)
        capture_event(
            _event_actor(session),
            "auth session failed",
            {
                "provider": session.provider,
                "flow_type": session.flow_type,
                "principal_id": session.principal_id,
            },
        )
        raise
    return _session_response(session, server_base_url)


@router.get("/callback/oauth", response_class=HTMLResponse)
async def oauth_callback(
    request: Request,
    sessions: AuthSessionStore = Depends(get_auth_sessions),
) -> Response:
    state = request.query_params.get("state")
    if not state:
        return HTMLResponse(pages.message_page("Authentication failed", "Missing OAuth state."), status_code=400)
    try:
        session = await sessions.get_by_oauth_state(state)
    except KeyError:
        return HTMLResponse(
            pages.message_page("Authentication session expired", "Please run authsome login again."),
            status_code=400,
        )
    if not await _ensure_browser_session_identity(request, session):
        return HTMLResponse(
            pages.message_page("Dashboard session expired", "Open the dashboard again to continue."),
            status_code=401,
        )
    callback_data = dict(request.query_params)
    auth = await require_auth_service(
        request,
        identity=session.identity,
        principal_id=session.principal_id,
        detail="Authentication session not found",
    )
    try:
        await auth.resume_login_flow(session, callback_data)
        session.state = AuthSessionStatus.COMPLETED
        session.status_message = "Login successful"
        await sessions.save(session)
        capture_event(
            _event_actor(session),
            "auth session completed",
            {
                "provider": session.provider,
                "flow_type": session.flow_type,
                "principal_id": session.principal_id,
            },
        )
    except Exception as exc:
        session.state = AuthSessionStatus.FAILED
        session.error_message = str(exc)
        await sessions.save(session)
        capture_event(
            _event_actor(session),
            "auth session failed",
            {
                "provider": session.provider,
                "flow_type": session.flow_type,
                "principal_id": session.principal_id,
            },
        )
        return HTMLResponse(pages.message_page("Authentication failed", str(exc)), status_code=400)
    if return_url := session.payload.get("return_url"):
        return RedirectResponse(str(return_url), status_code=303)
    return HTMLResponse(pages.message_page("Authentication successful", "You can close this window."))


@router.get("/sessions/{session_id}/input", response_class=HTMLResponse)
async def input_page(
    session_id: str,
    request: Request,
    sessions: AuthSessionStore = Depends(get_auth_sessions),
    server_base_url: str = Depends(get_server_base_url),
) -> HTMLResponse:
    try:
        session = await sessions.get(session_id)
    except KeyError:
        return HTMLResponse(
            pages.message_page("Authentication session expired", "Please run authsome login again."),
            status_code=404,
        )
    if not await _ensure_browser_session_identity(request, session):
        return HTMLResponse(
            pages.message_page("Dashboard session expired", "Open the dashboard again to continue."),
            status_code=401,
        )
    auth = await require_auth_service(
        request,
        identity=session.identity,
        principal_id=session.principal_id,
        detail="Authentication session not found",
    )
    definition = await auth.get_provider(session.provider)
    fields = session.payload.get("input_fields", [])

    callback_url = None
    if definition.auth_type == AuthType.OAUTH2:
        callback_url = build_callback_url(server_base_url)
    warning_message = None
    if session.payload.get("provider_config_only") and session.payload.get("existing_provider_client"):
        warning_message = "Changing these credentials will revoke existing connections for this provider."

    return HTMLResponse(
        pages.input_page(
            session.session_id,
            definition.display_name,
            definition.docs_url,
            fields,
            callback_url=callback_url,
            warning_message=warning_message,
        )
    )


@router.get("/sessions/{session_id}/device", response_class=HTMLResponse)
async def device_page(
    session_id: str,
    request: Request,
    sessions: AuthSessionStore = Depends(get_auth_sessions),
) -> HTMLResponse:
    try:
        session = await sessions.get(session_id)
    except KeyError:
        return HTMLResponse(
            pages.message_page("Authentication session expired", "Please run authsome login again."),
            status_code=404,
        )
    if not await _ensure_browser_session_identity(request, session):
        return HTMLResponse(
            pages.message_page("Dashboard session expired", "Open the dashboard again to continue."),
            status_code=401,
        )
    user_code = session.payload.get("user_code")
    verification_uri = session.payload.get("verification_uri")
    verification_uri_complete = session.payload.get("verification_uri_complete")
    if not user_code or not verification_uri:
        return HTMLResponse(
            pages.message_page("Invalid session", "This session does not have a device code."), status_code=400
        )
    auth = await require_auth_service(
        request,
        identity=session.identity,
        principal_id=session.principal_id,
        detail="Authentication session not found",
    )
    definition = await auth.get_provider(session.provider)
    return HTMLResponse(
        pages.device_code_page(definition.display_name, user_code, verification_uri, verification_uri_complete)
    )


@router.post("/sessions/{session_id}/input")
async def submit_input(
    session_id: str,
    request: Request,
    background_tasks: BackgroundTasks,
    sessions: AuthSessionStore = Depends(get_auth_sessions),
    server_base_url: str = Depends(get_server_base_url),
):
    try:
        session = await sessions.get(session_id)
    except KeyError:
        return HTMLResponse(
            pages.message_page("Authentication session expired", "Please run authsome login again."),
            status_code=404,
        )
    if not await _ensure_browser_session_identity(request, session):
        return HTMLResponse(
            pages.message_page("Dashboard session expired", "Open the dashboard again to continue."),
            status_code=401,
        )
    auth = await require_auth_service(
        request,
        identity=session.identity,
        principal_id=session.principal_id,
        detail="Authentication session not found",
    )
    form = await request.form()
    inputs = {key: str(value) for key, value in form.items()}

    if session.payload.get("provider_config_only"):
        all_vaults = await request.app.state.vault_registry.list_all()
        vault_ids = [vault.vault_id for vault in all_vaults] or ([auth.vault_id] if auth.vault_id else [])
        await auth.update_provider_configuration(session.provider, inputs, vault_ids=vault_ids)
        session.state = AuthSessionStatus.COMPLETED
        session.status_message = "Provider configuration updated"
        await sessions.save(session)
        if return_url := session.payload.get("return_url"):
            return RedirectResponse(str(return_url), status_code=303)
        return HTMLResponse(pages.message_page("Provider configuration updated", "You can close this window."))

    await auth.save_inputs(session, inputs)

    flow = FlowType(session.flow_type)
    if flow == FlowType.API_KEY:
        await auth.resume_login_flow(session, {})
        session.state = AuthSessionStatus.COMPLETED
        session.status_message = "Login successful"
        await sessions.save(session)
        capture_event(
            _event_actor(session),
            "auth session completed",
            {
                "provider": session.provider,
                "flow_type": session.flow_type,
                "principal_id": session.principal_id,
            },
        )
        if return_url := session.payload.get("return_url"):
            return RedirectResponse(str(return_url), status_code=303)
        return HTMLResponse(pages.message_page("Authentication successful", "You can close this window."))

    session.payload["callback_url_override"] = build_callback_url(server_base_url)
    await auth.begin_login_flow(
        session=session,
        scopes=session.payload.get("requested_scopes"),
        force=bool(session.payload.get("force", False)),
        base_url=session.payload.get("base_url"),
    )
    if flow == FlowType.DEVICE_CODE:
        _update_device_code_expiry(sessions, session)
        background_tasks.add_task(auth.background_resume, session)
        if session.payload.get("user_code") and session.payload.get("verification_uri"):
            await sessions.save(session)
            return RedirectResponse(url=build_device_url(server_base_url, session.session_id), status_code=303)

    await sessions.index_oauth_state(session)

    auth_url = session.payload.get("auth_url")
    if auth_url:
        await sessions.save(session)
        return RedirectResponse(str(auth_url), status_code=303)
    await sessions.save(session)
    return HTMLResponse(pages.message_page("Authentication started", "Return to your terminal to continue."))


def _update_device_code_expiry(sessions: AuthSessionStore, session: AuthSession) -> None:
    if "expires_in" in session.payload:
        try:
            session.expires_at = utc_now() + timedelta(seconds=int(session.payload["expires_in"]))
        except ValueError:
            pass


def _session_response(session: AuthSession, server_base_url: str) -> AuthSessionResponse:
    action: OpenUrlAction | BrowserAction | NoneAction = NoneAction()
    input_fields = session.payload.get("input_fields")
    if input_fields and session.state != AuthSessionStatus.COMPLETED:
        action = OpenUrlAction(type="open_url", url=build_auth_input_url(server_base_url, session.session_id))
    elif session.payload.get("browser_login") and session.state != AuthSessionStatus.COMPLETED:
        action = BrowserAction(
            entry_url=str(session.payload["entry_url"]),
            domains=session.payload.get("domains", []),
            auth_cookies=session.payload.get("auth_cookies", []),
            ttl_from_cookie=session.payload.get("ttl_from_cookie"),
            ttl_hours=int(session.payload.get("ttl_hours", 24)),
        )
    elif session.payload.get("auth_url"):
        action = OpenUrlAction(type="open_url", url=str(session.payload["auth_url"]))
    elif session.payload.get("verification_uri") and session.payload.get("user_code"):
        action = OpenUrlAction(
            type="open_url",
            url=build_device_url(server_base_url, session.session_id),
        )
    return AuthSessionResponse(
        id=session.session_id,
        provider=session.provider,
        connection=session.connection_name,
        status=session.state,
        message=session.status_message,
        error=session.error_message,
        created_at=session.created_at,
        expires_at=session.expires_at,
        next_action=action,
        user_code=session.payload.get("user_code"),
        verification_uri=session.payload.get("verification_uri"),
        verification_uri_complete=session.payload.get("verification_uri_complete"),
    )


def _field_to_payload(field: InputField) -> dict[str, Any]:
    return field.model_dump(mode="json", exclude_none=True)

