        connection_name=connection_name,
        auth_type=AuthType.API_KEY,
        status=ConnectionStatus.CONNECTED,
        api_key=api_key,
    )
    await auth._save_connection(record)
    await auth._update_provider_metadata(provider_name, connection_name)


